<script>
    const featuresData = [{
            title: "NDA Guaranteed",
            description: "Your ideas are protected from the very first interaction."
        },
        {
            title: "Expert Review",
            description: "Direct consultation with lead engineers, not sales reps."
        },
        {
            title: "Fixed Pricing",
            description: "No hidden costs. Clear milestones and transparent billing."
        }
    ];

    function renderFeatures(containerId, data) {
        const container = document.getElementById(containerId);

        container.innerHTML = data
            .map(item => `
                                        <div class="space-y-[2px] mt-4">
                                        <p class="font-bold text-[#ffda31] text-[13px] xl:text-[15px] uppercase">${item.title}</p>
                                        <p class="text-[#CBD5E1] text-[14px] xl:text-[16px]">${item.description}</p>
                                        </div>
                                    `)
            .join("");
    }

    renderFeatures("features", featuresData);
</script>


<style>
    /* Selected state (persistent) */
    .service-card.active-card {
        border-color: #FFCD3C !important;
        background-color: #FFFBEB !important;
        /* Light yellow bg */
        color: #000 !important;
        /* Black text */
    }

    .service-card.active-card svg {
        fill: currentColor !important;
        color: #D97706 !important;
        /* Black SVG on selected */
    }

    /* Hover on selected (keep yellow theme) */
    .service-card.active-card:hover {
        border-color: #FFCD3C !important;
        background-color: #FFFBEB !important;
        color: #000 !important;
    }
</style>


<script>
    document.addEventListener('DOMContentLoaded', () => {
        const cards = document.querySelectorAll('.service-card');
        const hiddenInput = document.getElementById('project_typeID');

        cards.forEach(card => {
            card.addEventListener('click', () => {
                cards.forEach(c => {
                    c.classList.remove('active-card');
                    const icon = c.querySelector('.check-icon');
                    if (icon) icon.classList.add('hidden');
                });

                card.classList.add('active-card');
                const icon = card.querySelector('.check-icon');
                if (icon) icon.classList.remove('hidden');

                hiddenInput.value = card.dataset.value;

                console.log('Selected:', hiddenInput.value);
            });
        });
    });
</script>


